function example() {
  const [query, setQuery] = useState('');
  const [searched, setSearched] = useState('');

  return (
    <form
      onSubmit={event => {
        event.preventDefault();
        setSearched(query);
      }}
    >
      <Field hasAddons>
        <Control isExpanded>
          <Input
            type="search"
            aria-label="Search the docs"
            value={query}
            onChange={event => setQuery(event.target.value)}
          />
        </Control>
        <Control>
          <IconButton
            icon="xmark"
            aria-label="Clear"
            onClick={() => setQuery('')}
          />
        </Control>
        <Control>
          <IconButton
            type="submit"
            color="primary"
            icon="magnifying-glass"
            aria-label="Search"
          />
        </Control>
      </Field>
      <Paragraph>
        {searched ? `Searched for ${searched}.` : 'No search yet.'}
      </Paragraph>
    </form>
  );
}
